// Des: Tests for ru-purg-clou: 90 to 80 rule, manifest first, keep latest, upgr mode
// Flo: fill the mock cloud with packs > purge at different caps > assert what is left
// I/O: mock cloud + temp db > pass or fail
// Run: zig build test
// ===================================================================
const std = @import("std"); const purg = @import("ru-purg-clou.zig"); const sync = @import("sy-clou-sync.zig"); const cmok = @import("sy-clou-mock.zig"); const outb = @import("sy-clou-outb.zig"); const inde = @import("st-page-inde.zig"); const sqli = @import("st-stor-sqli.zig");
const allo = std.testing.allocator;
const Rig = struct { tmpz: std.testing.TmpDir, cld: cmok.Mock, dirz: []u8, dbzz: sqli.Db, aren: std.heap.ArenaAllocator, syn: sync.Sync,
pub fn up(self: *Rig) !void { self.tmpz = std.testing.tmpDir(.{}); self.dirz = try std.fmt.allocPrint(allo, ".zig-cache/tmp/{s}", .{self.tmpz.sub_path}); self.dbzz = try inde.pageOpen(allo, std.testing.io, self.dirz); self.aren = std.heap.ArenaAllocator.init(allo); self.cld = cmok.Mock.init(allo); self.syn = .{ .iozz = std.testing.io, .dbzz = &self.dbzz, .dirz = self.dirz, .conf = .{}, .store = self.cld.store(), .sql = self.cld.sql() }; }
pub fn down(self: *Rig) void { self.cld.deinit(); self.aren.deinit(); self.dbzz.close(); allo.free(self.dirz); self.tmpz.cleanup(); }
pub fn pack(self: *Rig, name: []const u8, size: usize, hexz: []const u8) !void { const body = try allo.alloc(u8, size); defer allo.free(body); @memset(body, 'x'); try self.syn.store.put(self.syn.store.ctx, self.aren.allocator(), std.testing.io, name, body); var ins = try self.dbzz.prep("INSERT INTO pack(hexz,packk,offs,lenz) VALUES(?1,?2,0,1);"); defer ins.fini(); try ins.bindText(1, hexz); try ins.bindText(2, name); _ = try ins.step(); } };
fn five(rig: *Rig) !void { try rig.pack("runs/20260101.pack", 20, "h1"); try rig.pack("runs/20260102.pack", 20, "h2"); try rig.pack("runs/20260103.pack", 20, "h3"); try rig.pack("runs/20260104.pack", 20, "h4"); try rig.pack("runs/20260105.pack", 20, "h5"); }
test "below 90% nothing happens" { var rig: Rig = undefined; try rig.up(); defer rig.down(); try five(&rig); const res = try purg.purgRun(&rig.syn, rig.aren.allocator(), 100, 112); try std.testing.expectEqual(purg.Act.none, res.act); try std.testing.expectEqual(@as(usize, 5), rig.cld.map.count()); }
test "at 90% delete oldest packs until usage is at most 80%, manifest written first" { var rig: Rig = undefined; try rig.up(); defer rig.down(); try five(&rig); const res = try purg.purgRun(&rig.syn, rig.aren.allocator(), 100, 111); try std.testing.expectEqual(purg.Act.purged, res.act); try std.testing.expectEqual(@as(u32, 1), res.packs); try std.testing.expectEqual(@as(u64, 80), res.usage); try std.testing.expect(rig.cld.map.get("runs/20260101.pack") == null); try std.testing.expect(rig.cld.map.get("runs/20260102.pack") != null); try std.testing.expectEqual(@as(usize, 1), rig.cld.sawStmt("INTO cl_purg")); try std.testing.expectEqual(@as(usize, 1), rig.cld.sawStmt("DELETE FROM cl_manif")); const again = try purg.purgRun(&rig.syn, rig.aren.allocator(), 100, 111); try std.testing.expectEqual(purg.Act.none, again.act); }
test "a big overshoot repeats until under 80%" { var rig: Rig = undefined; try rig.up(); defer rig.down(); try five(&rig); const res = try purg.purgRun(&rig.syn, rig.aren.allocator(), 100, 100); try std.testing.expectEqual(@as(u32, 1), res.packs); try std.testing.expectEqual(@as(u64, 80), res.usage); const tight = try purg.purgRun(&rig.syn, rig.aren.allocator(), 100, 70); try std.testing.expectEqual(purg.Act.purged, tight.act); try std.testing.expect(tight.usage <= 56); }
test "the latest version of a URL survives: its file is requeued before the pack goes" { var rig: Rig = undefined; try rig.up(); defer rig.down(); try five(&rig); try inde.pageSet(&rig.dbzz, "http://a/live", .{ .hexz = "h1", .etag = "", .lmod = "", .code = 200, .tier = 1, .vend = "", .fetc = 1, .next = 2 }); const res = try purg.purgRun(&rig.syn, rig.aren.allocator(), 100, 111); try std.testing.expectEqual(@as(u32, 1), res.kept); try std.testing.expectEqual(@as(i64, 1), try outb.outbCont(&rig.dbzz, 0)); try std.testing.expect(rig.cld.map.get("runs/20260101.pack") == null); }
test "mode upgr only reports, deletes nothing" { var rig: Rig = undefined; try rig.up(); defer rig.down(); try five(&rig); rig.syn.conf.clou_poli_mode = "upgr"; const res = try purg.purgRun(&rig.syn, rig.aren.allocator(), 100, 111); try std.testing.expectEqual(purg.Act.upgr, res.act); try std.testing.expectEqual(@as(usize, 5), rig.cld.map.count()); }
test "if the manifest cannot be written, nothing is deleted" { var rig: Rig = undefined; try rig.up(); defer rig.down(); try five(&rig); rig.cld.sqlo = true; try std.testing.expectError(error.CloudSql, purg.purgRun(&rig.syn, rig.aren.allocator(), 100, 111)); try std.testing.expectEqual(@as(usize, 5), rig.cld.map.count()); }
